6	const SPHINX = "sphinx";
7	
8	const BASE_TYPE_COUNT = 3;
9	const SPHINX_POINTS = 1;
10	const BASE_BONUS = 1;
11	const BONUS_PER_EXTRA_TYPE = 2;
12	
13	const hasSphinx = (army: Card[]): boolean =>
14	  army.some((card) => card.monster === SPHINX);
15	
16	const countDistinctMonsterTypes = (army: Card[]): number =>
17	  new Set(army.map((card) => card.monster)).size;
18	
19	const countNonSphinxMonsterTypes = (army: Card[]): number =>
20	  countDistinctMonsterTypes(army) - 1;
21	
22	const bonusForVariety = (nonSphinxTypeCount: number): number => {
23	  const typesBeyondBase = nonSphinxTypeCount - BASE_TYPE_COUNT;
24	  return typesBeyondBase > 0
25	    ? BONUS_PER_EXTRA_TYPE * typesBeyondBase
26	    : BASE_BONUS;
27	};
28	
29	const countSphinxes = (army: Card[]): number =>
30	  army.filter((card) => card.monster === SPHINX).length;
31	
32	export const scoreArmy = (army: Card[]): number => {
33	  const scorePerSphinx =
34	    SPHINX_POINTS + bonusForVariety(countNonSphinxMonsterTypes(army));
35	  return countSphinxes(army) * scorePerSphinx;
36	};
